def get_chapter_meta(n: int):
    """Return chapter metadata (without body) for listing."""
    c = CHAPTERS.get(n)
    if not c:
        return None
    return {
        "n": n,
        "number": c["number"],
        "title": c["title"],
        "subtitle": c["subtitle"],
        "reading_time_min": c["reading_time_min"],
        "section_count": len(c["sections"]),
    }


def get_chapter(n: int):
    """Return full chapter content."""
    return CHAPTERS.get(n)
